const savedProductStorageKey = 'marketingCalcProductResultV1';

function readSavedProductCalculation() {
    try {
        const text = localStorage.getItem(savedProductStorageKey);
        if (!text) return null;
        const parsed = JSON.parse(text);
        if (!Array.isArray(parsed.productPortfolio) || !parsed.productPortfolio.length ||
            parsed.productPortfolio.length > 100) return null;
        const seen = new Set();
        for (const item of parsed.productPortfolio) {
            if (!item || !['own','resale','dropship','offline-service'].includes(item.source) ||
                !Number.isSafeInteger(Number(item.id)) || Number(item.id) <= 0 ||
                seen.has(Number(item.id)) ||
                typeof item.name !== 'string' || !item.name.trim() ||
                !item.inputs || typeof item.inputs !== 'object') return null;
            seen.add(Number(item.id));
        }
        return parsed;
    } catch (_) {
        return null;
    }
}

